interface StyleTokens {
  // Typography
  fontFamily: string | null
  fontWeight: string | null
  fontSize: string | null
  lineHeight: string | null
  letterSpacing: string | null
  textAlign: string | null
  textDecoration: string[]

  // Colors
  textColor: string | null
  backgroundColor: string | null
  borderColor: string | null

  // Layout
  margin: string[]
  padding: string[]

  // Border
  borderWidth: string | null
  borderStyle: string | null

  // Appearance
  opacity: string | null
  borderRadius: string | null
  shadow: string | null
}

const TAILWIND_PATTERNS = {
  // Typography
  fontFamily: /^font-(sans|serif|mono)$/,
  fontWeight: /^font-(thin|extralight|light|normal|medium|semibold|bold|extrabold|black)$/,
  fontSize: /^text-(xs|sm|base|lg|xl|2xl|3xl|4xl|5xl|6xl|7xl|8xl|9xl)$/,
  lineHeight: /^leading-(none|tight|snug|normal|relaxed|loose|[3-9]|10)$/,
  letterSpacing: /^tracking-(tighter|tight|normal|wide|wider|widest)$/,
  textAlign: /^text-(left|center|right|justify|start|end)$/,
  textDecoration: /^(italic|not-italic|underline|no-underline|line-through|overline)$/,

  // Colors
  textColor: /^text-(.+)$/,
  backgroundColor: /^bg-(.+)$/,
  borderColor: /^border-(.+)$/,

  // Layout
  margin: /^-?m[tlrbxy]?-(.+)$/,
  padding: /^p[tlrbxy]?-(.+)$/,

  // Border
  borderWidth: /^border(?:-([0248]|[tlrbxy]))?$/,
  borderStyle: /^border-(solid|dashed|dotted|double|none)$/,

  // Appearance
  opacity: /^opacity-(\d+|[05])$/,
  borderRadius: /^rounded(?:-(.+))?$/,
  shadow: /^shadow(?:-(.+))?$/,
} as const

export function parseTailwindClassName(className: string): StyleTokens {
  const result: StyleTokens = {
    fontFamily: null,
    fontWeight: null,
    fontSize: null,
    lineHeight: null,
    letterSpacing: null,
    textAlign: null,
    textDecoration: [],
    textColor: null,
    backgroundColor: null,
    borderColor: null,
    margin: [],
    padding: [],
    borderWidth: null,
    borderStyle: null,
    opacity: null,
    borderRadius: null,
    shadow: null,
  }

  const tokens = className.split(/\s+/).filter(Boolean)

  for (const token of tokens) {
    // Font family
    if (TAILWIND_PATTERNS.fontFamily.test(token)) {
      result.fontFamily = token
      continue
    }
    // Font weight
    if (TAILWIND_PATTERNS.fontWeight.test(token)) {
      result.fontWeight = token
      continue
    }
    // Font size
    if (TAILWIND_PATTERNS.fontSize.test(token)) {
      result.fontSize = token
      continue
    }
    // Line height
    if (TAILWIND_PATTERNS.lineHeight.test(token)) {
      result.lineHeight = token
      continue
    }
    // Letter spacing
    if (TAILWIND_PATTERNS.letterSpacing.test(token)) {
      result.letterSpacing = token
      continue
    }
    // Text alignment
    if (TAILWIND_PATTERNS.textAlign.test(token)) {
      result.textAlign = token
      continue
    }
    // Text decoration
    if (TAILWIND_PATTERNS.textDecoration.test(token)) {
      result.textDecoration.push(token)
      continue
    }
    // Text color (exclude font-size and alignment classes)
    if (
      TAILWIND_PATTERNS.textColor.test(token) &&
      !TAILWIND_PATTERNS.fontSize.test(token) &&
      !TAILWIND_PATTERNS.textAlign.test(token)
    ) {
      result.textColor = token
      continue
    }
    // Background color
    if (TAILWIND_PATTERNS.backgroundColor.test(token)) {
      result.backgroundColor = token
      continue
    }
    // Border color (exclude directional border classes)
    if (TAILWIND_PATTERNS.borderColor.test(token) && token !== 'border') {
      const borderMatch = token.match(/^border-(.+)$/)
      if (borderMatch && borderMatch[1]) {
        const borderValue = borderMatch[1]
        if (
          !['t', 'r', 'b', 'l', 'x', 'y', '0', '2', '4', '8'].includes(borderValue) &&
          !['solid', 'dashed', 'dotted', 'double', 'none'].includes(borderValue)
        ) {
          result.borderColor = token
        }
      }
      continue
    }
    // Border width
    if (TAILWIND_PATTERNS.borderWidth.test(token)) {
      result.borderWidth = token
      continue
    }
    // Border style
    if (TAILWIND_PATTERNS.borderStyle.test(token)) {
      result.borderStyle = token
      continue
    }
    // Margin
    if (TAILWIND_PATTERNS.margin.test(token)) {
      result.margin.push(token)
      continue
    }
    // Padding
    if (TAILWIND_PATTERNS.padding.test(token)) {
      result.padding.push(token)
      continue
    }
    // Opacity
    if (TAILWIND_PATTERNS.opacity.test(token)) {
      result.opacity = token
      continue
    }
    // Border radius
    if (TAILWIND_PATTERNS.borderRadius.test(token)) {
      result.borderRadius = token
      continue
    }
    // Shadow
    if (TAILWIND_PATTERNS.shadow.test(token)) {
      result.shadow = token
      continue
    }
  }

  return result
}
